import { useMemo, useState } from 'react';
import { Activity, BarChart3, CircleGauge, Droplets, Gauge, Lightbulb, Magnet, Orbit, Radio, SlidersHorizontal, Sparkles, Thermometer, Waves, Zap } from 'lucide-react';

const clamp = (value, min = 0, max = 100) => Math.min(max, Math.max(min, value));
const number = (values, key, fallback = 0) => Number(values[key] ?? fallback);
const format = (value, digits = 1) => Number.isFinite(value) ? Number(value).toFixed(digits).replace(/\.0+$/, '') : '—';
const series = (fn, count = 42) => Array.from({ length: count }, (_, index) => {
  const x = index / (count - 1);
  return { x, y: fn(x) };
});
const normalise = (points) => {
  const ys = points.map((point) => point.y);
  const min = Math.min(...ys);
  const max = Math.max(...ys);
  const span = max - min || 1;
  return points.map((point) => ({ ...point, y: (point.y - min) / span }));
};
const optionNumber = (value, map) => map[value] ?? map.Default ?? 1;
export default function InteractiveLab({ practical }) {
  const fields = practical.interactive?.fields || [];
  const [values, setValues] = useState(() => Object.fromEntries(fields.map((field) => [field.key, field.value])));
  const model = useMemo(() => calculateModel(practical.interactive?.model, values), [practical.interactive?.model, values]);
  const update = (field, value) => setValues((current) => ({ ...current, [field.key]: field.type === 'range' ? Number(value) : value }));
  return <section className="interactive-lab" aria-label={`${practical.title} interactive experiment`}>
    <div className="interactive-lab-heading"><div><span className="eyebrow"><SlidersHorizontal size={13} /> LIVE EXPERIMENT</span><h3>Change an input. Watch the evidence move.</h3></div><span className="live-indicator"><i /> Updating live</span></div>
    <div className="lab-layout">
      <aside className="lab-controls"><div className="lab-panel-label">INPUT CONTROLS</div>{fields.map((field) => <Control key={field.key} field={field} value={values[field.key]} onChange={(value) => update(field, value)} />)}<div className="lab-control-note"><Sparkles size={14} /><span>Change one variable at a time to see its effect.</span></div></aside>
      <div className="lab-main"><div className="lab-stage"><div className="lab-stage-top"><span className="lab-stage-kicker">VIRTUAL MODEL</span><span className="lab-stage-status">{model.status}</span></div><LabVisual visual={model.visual} /><p className="lab-stage-caption">{model.caption}</p></div><Chart points={model.graph.points} label={model.graph.label} xLabel={model.graph.xLabel} yLabel={model.graph.yLabel} tone={model.graph.tone} /></div>
      <aside className="lab-results"><div className="lab-panel-label">MEASUREMENTS</div><div className="lab-metrics">{model.metrics.map((metric) => <div className="lab-metric" key={metric.label}><span>{metric.label}</span><strong>{metric.value}<small>{metric.unit}</small></strong></div>)}</div><div className="lab-readout"><div><span className="lab-panel-label">OBSERVATION TABLE</span><BarChart3 size={15} /></div><p>{model.readout}</p><div className="lab-mini-bars">{model.bars.map((bar) => <span key={bar.label}><i style={{ height: `${clamp(bar.value)}%` }} /><small>{bar.label}</small></span>)}</div></div></aside>
    </div>
  </section>;
}

function Control({ field, value, onChange }) {
  if (field.type === 'select') return <label className="lab-control"><span>{field.label}</span><select value={value} onChange={(event) => onChange(event.target.value)}>{field.options.map((option) => <option key={option}>{option}</option>)}</select></label>;
  if (field.type === 'toggle') return <div className="lab-control lab-control--toggle"><span>{field.label}</span><button type="button" className={`toggle-switch ${value ? 'on' : ''}`} aria-pressed={value} onClick={() => onChange(!value)}><i /></button></div>;
  return <label className="lab-control"><span><b>{field.label}</b><em>{format(value, field.step < 1 ? 1 : 0)} {field.unit}</em></span><input type="range" min={field.min} max={field.max} step={field.step} value={value} onChange={(event) => onChange(event.target.value)} /><div className="lab-range"><small>{field.min} {field.unit}</small><small>{field.max} {field.unit}</small></div></label>;
}

function Chart({ points, label, xLabel, yLabel, tone = 'green' }) {
  const safePoints = normalise(points || series((x) => x));
  const polyline = safePoints.map((point) => `${point.x * 250 + 12},${76 - point.y * 55}`).join(' ');
  const area = `12,76 ${polyline} 262,76`;
  return <div className="lab-chart"><div className="lab-chart-top"><span className="lab-panel-label">{label}</span><span><i className={`chart-dot chart-dot--${tone}`} /> Live data</span></div><svg viewBox="0 0 274 92" role="img" aria-label={`${label} live graph`}><path className="chart-axis" d="M12 8V76H262" /><path className="chart-grid" d="M12 22H262M12 40H262M12 58H262" /><polygon className={`chart-area chart-area--${tone}`} points={area} /><polyline className={`chart-line chart-line--${tone}`} points={polyline} /></svg><div className="chart-axis-labels"><span>{yLabel}</span><span>{xLabel}</span></div></div>;
}

function LabVisual({ visual }) {
  const { kind, ...data } = visual;
  if (kind === 'circuit') return <div className="visual-circuit"><span className="visual-wire visual-wire--top" /><span className="visual-wire visual-wire--bottom" /><span className="visual-battery"><b>+</b><b>−</b><small>source</small></span><span className="visual-resistor">R</span><span className={`visual-lamp ${data.active ? 'active' : ''}`}><Lightbulb size={22} /><small>{data.active ? 'ON' : 'OFF'}</small></span><span className="visual-current">{data.current} A</span></div>;
  if (kind === 'trajectory') return <div className="visual-trajectory"><span className="visual-ground" /><svg viewBox="0 0 310 150"><path className="trajectory-grid" d="M20 25H290M20 55H290M20 85H290M20 115H290M60 10V135M120 10V135M180 10V135M240 10V135" /><polyline points={data.path} /><circle cx={data.ball.x} cy={data.ball.y} r="6" /><path className="trajectory-vector" d={`M${data.ball.x} ${data.ball.y} l28 -10`} /></svg><span className="trajectory-label">{data.range} m range</span></div>;
  if (kind === 'wave') return <div className="visual-wave"><div className="wave-object" style={{ transform: `translateY(${data.position}px)` }} /><svg viewBox="0 0 310 110"><path className="wave-mid" d="M10 55H300" /><polyline points={data.path} /></svg><span>{data.period} s period</span></div>;
  if (kind === 'rays') return <div className="visual-rays"><div className="medium medium--one">{data.medium1}</div><div className="medium medium--two">{data.medium2}</div><svg viewBox="0 0 310 150"><path className="ray-normal" d="M155 8V142" /><path className="ray-line ray-line--incident" d={data.incident} /><path className={`ray-line ${data.tir ? 'ray-line--tir' : ''}`} d={data.refracted} /></svg><span>{data.message}</span></div>;
  if (kind === 'coil') return <div className="visual-coil"><div className={`magnet ${data.reverse ? 'reverse' : ''}`}><Magnet size={27} /><small>MAGNET</small></div><div className="coil-rings">{Array.from({ length: 5 }, (_, index) => <i key={index} />)}</div><div className={`galvanometer ${data.positive ? 'positive' : 'negative'}`}><span>{data.emf} V</span><i /></div><small className="coil-caption">Move to induce current</small></div>;
  if (kind === 'particles') return <div className="visual-particles"><div className="particle-vessel">{data.particles.map((particle, index) => <i key={index} style={{ left: `${particle.x}%`, top: `${particle.y}%`, animationDelay: `${particle.delay}s` }} />)}<strong>{data.label}</strong></div><span>{data.rate}</span></div>;
  if (kind === 'bubbles') return <div className="visual-electrolysis"><div className="electrode"><span>{data.leftLabel}</span>{data.leftBubbles.map((bubble) => <i key={bubble} style={{ left: `${bubble}%` }} />)}</div><div className="electrolyte-line" /><div className="electrode"><span>{data.rightLabel}</span>{data.rightBubbles.map((bubble) => <i key={bubble} style={{ left: `${bubble}%` }} />)}</div><small>{data.gas} gas collected</small></div>;
  if (kind === 'bars') return <div className="visual-bars"><div className="bar-stage">{data.bars.map((bar) => <div key={bar.label}><i style={{ height: `${clamp(bar.value)}%` }} /><span>{bar.label}</span></div>)}</div><strong>{data.center}</strong><small>{data.sub}</small></div>;
  if (kind === 'thermometer') return <div className="visual-thermometer"><div className="thermometer"><i style={{ height: `${clamp(data.level)}%` }} /><b /></div><div><strong>{data.temperature}°C</strong><small>{data.state}</small></div><span className="heat-wave">∿ ∿ ∿</span></div>;
  if (kind === 'plant') return <div className="visual-plant"><div className="plant-pot"><i className="plant-stem" style={{ height: `${clamp(data.height)}%` }} /><i className="plant-leaf plant-leaf--one" /><i className="plant-leaf plant-leaf--two" /><b /></div><div><strong>{data.height} cm</strong><small>{data.health}</small></div></div>;
  if (kind === 'cells') return <div className="visual-cells"><div className="cell-membrane">{data.cells.map((cell, index) => <i key={index} style={{ left: `${cell.x}%`, top: `${cell.y}%`, opacity: cell.opacity }} />)}<strong>{data.direction}</strong></div><span>{data.mass} g tissue mass</span></div>;
  if (kind === 'heart') return <div className="visual-heart"><div className="heart-orbit" /><div className="heart-core">♥</div><strong>{data.bpm} <small>BPM</small></strong><span>{data.phase}</span></div>;
  if (kind === 'soil') return <div className="visual-soil"><div className="soil-profile">{data.layers.map((layer) => <i key={layer.label} style={{ height: `${layer.value}%`, background: layer.color }}><small>{layer.label}</small></i>)}</div><div><strong>{data.yield}%</strong><small>yield potential</small></div></div>;
  if (kind === 'seeds') return <div className="visual-seeds"><div className="seed-tray">{data.seeds.map((seed, index) => <i key={index} className={seed.grown ? 'grown' : ''} style={{ '--seed-delay': `${index * 0.18}s` }} />)}</div><strong>{data.germinated}% germinated</strong><small>{data.rate} growth rate</small></div>;
  if (kind === 'irrigation') return <div className="visual-irrigation"><div className="rain-lines">{Array.from({ length: 7 }, (_, index) => <i key={index} style={{ left: `${10 + index * 13}%`, animationDelay: `${index * 0.1}s` }} />)}</div><div className="irrigation-ground"><i className="irrigation-plant" /><span className="water-level" style={{ width: `${data.water}%` }} /></div><div><strong>{data.efficiency}%</strong><small>water efficiency</small></div></div>;
  if (kind === 'climate') return <div className="visual-climate"><div className="climate-globe"><span className="cloud cloud--one" /><span className="cloud cloud--two" /><i style={{ transform: `rotate(${data.ice}deg)` }} /></div><div><strong>+{data.temperature}°C</strong><small>model warming</small><em>{data.seaLevel} cm sea-level rise</em></div></div>;
  if (kind === 'cycle') return <div className="visual-cycle"><div className="cycle-node cycle-node--air">ATMOSPHERE<br /><strong>{data.co2} ppm</strong></div><div className="cycle-node cycle-node--plant">PLANTS</div><div className="cycle-node cycle-node--ocean">OCEAN</div><span className="cycle-arrow cycle-arrow--one">↘</span><span className="cycle-arrow cycle-arrow--two">↗</span><span className="cycle-arrow cycle-arrow--three">↔</span></div>;
  if (kind === 'city') return <div className="visual-city"><div className="city-sky"><span className="sun" />{data.towers.map((tower, index) => <i key={index} style={{ height: `${tower}%` }} />)}<span className="smog" style={{ opacity: data.smog / 100 }} /></div><div><strong>AQI {data.aqi}</strong><small>{data.health}</small></div></div>;
  if (kind === 'foodweb') return <div className="visual-foodweb"><div className="web-lines" /><span className="web-node web-node--one">PLANTS</span><span className="web-node web-node--two">INSECTS</span><span className="web-node web-node--three">BIRDS</span><span className="web-node web-node--four">PREDATOR</span><strong>{data.species} species</strong><small>{data.risk}% extinction risk</small></div>;
  if (kind === 'logic') return <div className="visual-logic"><div className="logic-input"><span className={data.a ? 'on' : ''}>A {data.a ? 1 : 0}</span><span className={data.b ? 'on' : ''}>B {data.b ? 1 : 0}</span></div><div className="logic-gate">{data.gate}</div><div className={`logic-output ${data.output ? 'on' : ''}`}><Lightbulb size={20} /><span>OUT {data.output ? 1 : 0}</span></div><small>Truth-table row updates instantly</small></div>;
  if (kind === 'transistor') return <div className="visual-transistor"><div className={`transistor-led ${data.on ? 'on' : ''}`} /><svg viewBox="0 0 220 110"><path d="M20 83H200M35 90V20M35 83L178 24" /><polyline points={data.path} /></svg><strong>{data.current} mA</strong><small>{data.region}</small></div>;
  if (kind === 'rc') return <div className="visual-rc"><div className={`capacitor ${data.full ? 'full' : ''}`}><i style={{ height: `${data.level}%` }} /><b>+</b><b>−</b></div><div className="rc-wire" /><div><strong>τ {data.tau} ms</strong><small>{data.level}% charged</small></div></div>;
  if (kind === 'feedback') return <div className="visual-feedback"><div className="gauge"><i style={{ transform: `rotate(${data.angle}deg)` }} /><b>{data.input}%</b></div><div className="feedback-arrow">→</div><div className={`actuator actuator--${data.actuator.toLowerCase()} ${data.active ? 'active' : ''}`}><Zap size={22} /><strong>{data.active ? 'ON' : 'OFF'}</strong></div><small>Threshold {data.threshold}%</small></div>;
  return <div className="visual-generic"><Gauge size={32} /><strong>{data.center || 'Live response'}</strong><small>{data.sub || 'Model output updates with your inputs'}</small></div>;
}

function calculateModel(model, v) {
  switch (model) {
    case 'circuit': return circuitModel(v);
    case 'projectile': return projectileModel(v);
    case 'oscillation': return oscillationModel(v);
    case 'refraction': return refractionModel(v);
    case 'induction': return inductionModel(v);
    case 'titration': return titrationModel(v);
    case 'reaction-rate': return reactionRateModel(v);
    case 'electrolysis': return electrolysisModel(v);
    case 'equilibrium': return equilibriumModel(v);
    case 'calorimetry': return calorimetryModel(v);
    case 'photosynthesis': return photosynthesisModel(v);
    case 'enzyme': return enzymeModel(v);
    case 'osmosis': return osmosisModel(v);
    case 'respirometer': return respirometerModel(v);
    case 'heart-rate': return heartModel(v);
    case 'soil-growth': return soilGrowthModel(v);
    case 'germination': return germinationModel(v);
    case 'irrigation': return irrigationModel(v);
    case 'fertilizer': return fertilizerModel(v);
    case 'pest-yield': return pestModel(v);
    case 'water-quality': return waterQualityModel(v);
    case 'greenhouse': return greenhouseModel(v);
    case 'carbon-cycle': return carbonModel(v);
    case 'air-quality': return airQualityModel(v);
    case 'biodiversity': return biodiversityModel(v);
    case 'resistor-network': return resistorNetworkModel(v);
    case 'logic': return logicModel(v);
    case 'transistor': return transistorModel(v);
    case 'rc': return rcModel(v);
    case 'feedback': return feedbackModel(v);
    default: return genericModel(v);
  }
}

function result({ status = 'Stable', caption, metrics, graph, bars, readout, visual }) { return { status, caption, metrics, graph, bars, readout, visual }; }
function metric(label, value, unit = '') { return { label, value: format(value), unit }; }
function gravity(value) { return optionNumber(value, { Earth: 9.81, Moon: 1.62, Mars: 3.71 }); }
function circuitModel(v) { const voltage = number(v, 'voltage', 12); const resistance = number(v, 'resistance', 24); const parallel = v.connection === 'Parallel'; const equivalent = parallel ? resistance / 2 : resistance * 2; const current = v.closed === false ? 0 : voltage / equivalent; return result({ status: v.closed === false ? 'Switch open' : 'Current flowing', caption: `${parallel ? 'Parallel' : 'Series'} circuit · close the switch and compare the live readings.`, metrics: [metric('Current', current, ' A'), metric('Equivalent R', equivalent, ' Ω'), metric('Power', voltage * current, ' W'), metric('Brightness', clamp(current * 8), '%')], graph: { label: 'Current vs voltage', xLabel: 'Voltage', yLabel: 'Current', tone: 'blue', points: series((x) => v.closed === false ? 0 : x * voltage / equivalent) }, bars: [{ label: 'V', value: voltage / 24 * 100 }, { label: 'I', value: current * 100 }, { label: 'P', value: clamp(voltage * current / 8 * 100) }], readout: `At ${format(voltage)} V and ${format(equivalent)} Ω, the circuit current is ${format(current, 2)} A.`, visual: { kind: 'circuit', active: v.closed !== false, current: format(current, 2) } }); }
function projectileModel(v) { const angle = number(v, 'angle', 45) * Math.PI / 180; const speed = number(v, 'speed', 24); const g = gravity(v.gravity); const resistance = v.airResistance ? 0.78 : 1; const range = speed ** 2 * Math.sin(2 * angle) / g * resistance; const height = speed ** 2 * Math.sin(angle) ** 2 / (2 * g) * resistance; const flight = 2 * speed * Math.sin(angle) / g; const path = series((x) => Math.sin(Math.PI * x) * 105, 32).map((p) => `${20 + p.x * 270},${130 - p.y}`).join(' '); const ball = { x: 20 + clamp((number(v, 'angle', 45) / 80) * 270, 0, 270), y: 130 - Math.sin(Math.PI * clamp(number(v, 'angle', 45) / 80, 0, 1)) * 105 }; return result({ status: v.airResistance ? 'Drag enabled' : 'Ideal trajectory', caption: `${v.gravity || 'Earth'} gravity · the launch vector and range respond to angle and speed.`, metrics: [metric('Range', range, ' m'), metric('Max height', height, ' m'), metric('Flight time', flight, ' s'), metric('Gravity', g, ' m/s²')], graph: { label: 'Height over time', xLabel: 'Time', yLabel: 'Height', tone: 'blue', points: series((x) => Math.sin(Math.PI * x) * height) }, bars: [{ label: 'Range', value: clamp(range / 70 * 100) }, { label: 'Height', value: clamp(height / 35 * 100) }, { label: 'Time', value: clamp(flight / 8 * 100) }], readout: `The projectile reaches ${format(height)} m after launching at ${format(number(v, 'angle', 45))}°.`, visual: { kind: 'trajectory', path, ball, range: format(range) } }); }
function oscillationModel(v) { const mass = number(v, 'mass', 1); const k = number(v, 'springConstant', 20); const amplitude = number(v, 'amplitude', 10); const g = gravity(v.gravity); const period = 2 * Math.PI * Math.sqrt(mass / k); const energy = 0.5 * k * (amplitude / 100) ** 2; return result({ status: 'Oscillating', caption: 'Displacement, velocity and energy are linked across one repeating cycle.', metrics: [metric('Period', period, ' s'), metric('Energy', energy, ' J'), metric('Peak speed', (2 * Math.PI / period) * amplitude / 100, ' m/s'), metric('Gravity', g, ' m/s²')], graph: { label: 'Displacement-time', xLabel: 'Time', yLabel: 'Displacement', tone: 'mint', points: series((x) => Math.sin(x * Math.PI * 2) * amplitude) }, bars: [{ label: 'Disp.', value: amplitude * 5 }, { label: 'Speed', value: clamp(100 / period / 2) }, { label: 'Energy', value: clamp(energy * 100) }], readout: `A ${format(mass)} kg mass on a ${format(k)} N/m spring completes a cycle in ${format(period, 2)} s.`, visual: { kind: 'wave', path: series((x) => Math.sin(x * Math.PI * 2) * 35 + 55, 32).map((p) => `${10 + p.x * 290},${p.y}`).join(' '), position: Math.sin(amplitude) * 8, period: format(period, 2) } }); }
function refractionModel(v) { const incidence = number(v, 'incidence', 38); const n1 = number(v, 'n1', 1.5); const n2 = number(v, 'n2', 1); const sinR = n1 * Math.sin(incidence * Math.PI / 180) / n2; const tir = sinR > 1; const refractedAngle = tir ? 90 : Math.asin(sinR) * 180 / Math.PI; const critical = n1 > n2 ? Math.asin(n2 / n1) * 180 / Math.PI : null; const incident = `M155 75 L${155 - Math.sin(incidence * Math.PI / 180) * 105} ${75 - Math.cos(incidence * Math.PI / 180) * 105}`; const refracted = tir ? 'M155 75 L25 75' : `M155 75 L${155 + Math.sin(refractedAngle * Math.PI / 180) * 105} ${75 + Math.cos(refractedAngle * Math.PI / 180) * 105}`; return result({ status: tir ? 'Total internal reflection' : 'Ray refracted', caption: tir ? 'The incident angle is beyond the critical angle.' : 'Measure both rays and compare them with Snell’s law.', metrics: [metric('Refracted angle', refractedAngle, '°'), metric('Critical angle', critical || 0, critical ? '°' : '—'), metric('Wavelength', number(v, 'wavelength', 550), ' nm'), metric('n₁ → n₂', n1 / n2, '')], graph: { label: 'Refracted angle', xLabel: 'Incidence', yLabel: 'Angle', tone: 'blue', points: series((x) => Math.min(1, n1 / n2 * Math.sin(x * Math.PI / 2))) }, bars: [{ label: 'Inc.', value: incidence / 90 * 100 }, { label: 'Ref.', value: refractedAngle / 90 * 100 }, { label: 'Crit.', value: critical ? critical / 90 * 100 : 100 }], readout: tir ? 'The ray remains in the first medium: total internal reflection is visible.' : `The ray bends to ${format(refractedAngle)}° in medium 2.`, visual: { kind: 'rays', medium1: `n = ${format(n1, 1)}`, medium2: `n = ${format(n2, 1)}`, incident, refracted, tir, message: tir ? 'TIR' : `${format(refractedAngle)}°` } }); }
function inductionModel(v) { const emf = number(v, 'magnetSpeed', 5) * number(v, 'fieldStrength', 1) * number(v, 'turns', 80) / 100; const current = emf / 12; return result({ status: emf > 0.1 ? 'EMF induced' : 'No change in flux', caption: 'Move the magnet faster or add turns to make the galvanometer respond.', metrics: [metric('Induced emf', emf, ' V'), metric('Current', current, ' A'), metric('Flux change', number(v, 'fieldStrength', 1) * number(v, 'magnetSpeed', 5), ' Wb/s'), metric('Turns', number(v, 'turns', 80), '')], graph: { label: 'Induced emf', xLabel: 'Time', yLabel: 'EMF', tone: 'gold', points: series((x) => Math.sin(x * Math.PI * 4) * emf) }, bars: [{ label: 'Speed', value: number(v, 'magnetSpeed', 5) * 10 }, { label: 'Field', value: number(v, 'fieldStrength', 1) * 50 }, { label: 'Turns', value: number(v, 'turns', 80) / 2 }], readout: `${v.reverse ? 'Reversed motion changes polarity.' : 'The galvanometer deflects in the forward direction.'} Faraday’s law responds to changing flux.`, visual: { kind: 'coil', emf: format(emf, 2), positive: !v.reverse, reverse: v.reverse } }); }
function titrationModel(v) { const acid = number(v, 'acidConc', 0.2); const base = number(v, 'baseConc', 0.2); const volume = number(v, 'volume', 20); const eq = acid * 25 / base; const pH = volume < eq ? 3 + volume / Math.max(eq, 1) * 3.5 : 7 + Math.min(7, (volume - eq) / Math.max(eq, 1) * 5); return result({ status: Math.abs(volume - eq) < 2 ? 'Near equivalence' : volume > eq ? 'Base in excess' : 'Acid in excess', caption: 'Drop-by-drop titration · the steep pH region marks the equivalence point.', metrics: [metric('pH', pH, ''), metric('Equivalence', eq, ' mL'), metric('Added', volume, ' mL'), metric('Drop rate', number(v, 'dropRate', 4), ' /s')], graph: { label: 'Titration curve', xLabel: 'Base volume', yLabel: 'pH', tone: 'coral', points: series((x) => 1 / (1 + Math.exp(-(x - eq / 50) * 18))) }, bars: [{ label: 'pH', value: pH / 14 * 100 }, { label: 'Eq.', value: eq / 50 * 100 }, { label: 'Vol.', value: volume / 50 * 100 }], readout: `At ${format(volume)} mL added, the pH meter reads ${format(pH, 2)}.`, visual: { kind: 'bars', bars: [{ label: 'Acid', value: 100 - pH / 14 * 100 }, { label: 'Buffer', value: Math.max(8, 70 - Math.abs(volume - eq) * 4) }, { label: 'Base', value: pH / 14 * 100 }], center: `pH ${format(pH, 2)}`, sub: 'Indicator colour follows pH' } }); }
function reactionRateModel(v) { const concentration = number(v, 'concentration', 1); const temp = number(v, 'temperature', 25); const rate = concentration * (1 + (temp - 10) / 60) * (v.catalyst ? 1.7 : 1); return result({ status: v.catalyst ? 'Catalyst active' : 'Reaction running', caption: 'Particles collide more effectively when concentration, temperature or catalyst increases.', metrics: [metric('Relative rate', rate, '×'), metric('Half-time', 12 / rate, ' s'), metric('Collisions', rate * 18, ' /s'), metric('Temperature', temp, '°C')], graph: { label: 'Reactant concentration', xLabel: 'Time', yLabel: 'Concentration', tone: 'coral', points: series((x) => Math.exp(-x * rate)) }, bars: [{ label: 'Conc.', value: concentration * 50 }, { label: 'Temp.', value: temp / 80 * 100 }, { label: 'Catalyst', value: v.catalyst ? 100 : 18 }], readout: `The model rate is ${format(rate, 2)}× baseline, so product forms faster when the curve falls more steeply.`, visual: { kind: 'particles', label: v.catalyst ? 'Catalysed collisions' : 'Reactant collisions', rate: `${format(rate, 2)}× rate`, particles: particleSet(v.catalyst ? 22 : 12) } }); }
function electrolysisModel(v) { const voltage = number(v, 'voltage', 6); const time = number(v, 'time', 5); const gas = voltage * time * (v.electrolyte === 'Water' ? 0.8 : 1.2); return result({ status: voltage > 2 ? 'Electrolysis running' : 'Below threshold', caption: 'Bubble formation and electrode readings respond to voltage, electrolyte and time.', metrics: [metric('Gas volume', gas, ' mL'), metric('Charge', voltage * time * 2, ' C'), metric('Cathode gain', v.electrode === 'Copper' ? 0.8 : 0, ' g'), metric('Voltage', voltage, ' V')], graph: { label: 'Gas collected', xLabel: 'Time', yLabel: 'Volume', tone: 'blue', points: series((x) => x * gas) }, bars: [{ label: 'Gas', value: gas / 80 * 100 }, { label: 'Charge', value: voltage / 12 * 100 }, { label: 'Mass', value: v.electrode === 'Copper' ? 60 : 8 }], readout: `${v.electrolyte} produces ${format(gas)} mL of model gas after ${time} minutes.`, visual: { kind: 'bubbles', leftLabel: 'Cathode', rightLabel: 'Anode', leftBubbles: Array.from({ length: Math.max(2, Math.round(gas / 10)) }, (_, i) => 16 + i * 12), rightBubbles: Array.from({ length: Math.max(1, Math.round(gas / 18)) }, (_, i) => 22 + i * 18), gas: format(gas) } }); }
function equilibriumModel(v) { const shift = (number(v, 'concentration', 1) - 1) * 20 + (number(v, 'pressure', 1) - 1) * 12 - (number(v, 'temperature', 35) - 35) * 0.5; const product = clamp(50 + shift); return result({ status: Math.abs(shift) < 6 ? 'Equilibrium steady' : shift > 0 ? 'Shifted to products' : 'Shifted to reactants', caption: 'The system settles after each disturbance instead of stopping the forward and reverse reactions.', metrics: [metric('Product share', product, '%'), metric('Reactant share', 100 - product, '%'), metric('Pressure', number(v, 'pressure', 1), ' atm'), metric('Temperature', number(v, 'temperature', 35), '°C')], graph: { label: 'Concentration to equilibrium', xLabel: 'Time', yLabel: 'Share', tone: 'coral', points: series((x) => 0.5 + (product / 100 - 0.5) * (1 - Math.exp(-x * 7))) }, bars: [{ label: 'React.', value: 100 - product }, { label: 'Product', value: product }, { label: 'Shift', value: Math.abs(shift) * 2 }], readout: `The selected disturbance leaves ${format(product)}% of the model mixture on the product side.`, visual: { kind: 'bars', bars: [{ label: 'Reactants', value: 100 - product }, { label: 'Products', value: product }], center: `${format(product)}%`, sub: v.reaction === 'Cobalt chloride' ? 'Colour intensity' : 'Equilibrium position' } }); }
function calorimetryModel(v) { const moles = Math.min(number(v, 'acidConc', 0.5), number(v, 'baseConc', 0.5)) * number(v, 'volume', 100) / 1000; const delta = moles * 57.3 / (number(v, 'volume', 100) / 1000) / 4.18; const peak = number(v, 'initialTemp', 22) + delta; return result({ status: 'Heat released', caption: 'The thermometer rises after mixing, peaks and then cools toward room temperature.', metrics: [metric('Peak temperature', peak, '°C'), metric('ΔT', delta, '°C'), metric('Energy', moles * 57.3, ' kJ'), metric('Enthalpy', -57.3, ' kJ/mol')], graph: { label: 'Temperature-time', xLabel: 'Time', yLabel: 'Temp.', tone: 'gold', points: series((x) => number(v, 'initialTemp', 22) + delta * (1 - Math.exp(-x * 10)) * Math.exp(-x * 0.5)) }, bars: [{ label: 'Start', value: number(v, 'initialTemp', 22) * 2 }, { label: 'Peak', value: peak * 2 }, { label: 'ΔT', value: delta * 15 }], readout: `The mixture peaks at ${format(peak)}°C, an estimated ${format(delta)}°C rise above the starting temperature.`, visual: { kind: 'thermometer', level: peak / 60 * 100, temperature: format(peak), state: 'Peak after mixing' } }); }
function photosynthesisModel(v) { const colour = optionNumber(v.colour, { White: 1, Red: 0.9, Blue: 0.85, Green: 0.35 }); const temp = Math.max(0, 1 - Math.abs(number(v, 'temperature', 25) - 27) / 25); const rate = Math.min(100, number(v, 'light', 70) * number(v, 'co2', 50) / 70 * colour * temp); return result({ status: 'Oxygen bubbles visible', caption: 'Count the bubbles as the limiting factor changes.', metrics: [metric('Bubble rate', rate / 5, ' /min'), metric('Photosynthesis', rate, '%'), metric('CO₂ used', rate * 0.6, ' units'), metric('Temperature', number(v, 'temperature', 25), '°C')], graph: { label: 'Oxygen production', xLabel: 'Time', yLabel: 'Rate', tone: 'mint', points: series((x) => rate * (1 - Math.exp(-x * 4))) }, bars: [{ label: 'Light', value: number(v, 'light', 70) }, { label: 'CO₂', value: number(v, 'co2', 50) }, { label: 'Rate', value: rate }], readout: `${format(rate / 5)} oxygen bubbles per minute in the current setup.`, visual: { kind: 'plant', height: clamp(rate), health: `${v.colour} light · ${format(rate)}% rate` } }); }
function enzymeModel(v) { const ph = number(v, 'pH', 7); const phFactor = Math.max(0, 1 - Math.abs(ph - 7) / 5); const temp = number(v, 'temperature', 37); const tempFactor = temp > 55 ? Math.max(0.1, 1 - (temp - 55) / 25) : Math.max(0, 1 - Math.abs(temp - 37) / 45); const rate = number(v, 'enzymeConc', 1) * number(v, 'substrateConc', 1) * phFactor * tempFactor; return result({ status: temp > 60 ? 'Denaturation visible' : 'Active site working', caption: 'Collision frequency and active-site shape determine product formation.', metrics: [metric('Relative rate', rate, '×'), metric('Optimum pH gap', Math.abs(ph - 7), ''), metric('Product', rate * 42, ' units'), metric('Temperature', temp, '°C')], graph: { label: 'Product formation', xLabel: 'Time', yLabel: 'Product', tone: 'mint', points: series((x) => rate * (1 - Math.exp(-x * 5))) }, bars: [{ label: 'Enzyme', value: number(v, 'enzymeConc', 1) * 50 }, { label: 'pH', value: ph / 14 * 100 }, { label: 'Rate', value: rate * 50 }], readout: `The current conditions give a ${format(rate, 2)}× relative enzyme rate.`, visual: { kind: 'particles', label: temp > 60 ? 'Denatured active sites' : 'Enzyme collisions', rate: `${format(rate, 2)}× product rate`, particles: particleSet(Math.round(8 + rate * 12)) } }); }
function osmosisModel(v) { const gradient = 0.5 - number(v, 'solutionConc', 0.4); const temp = number(v, 'temperature', 25); const rate = gradient * (0.5 + temp / 50); const mass = 100 + gradient * 28; return result({ status: gradient > 0.02 ? 'Water enters tissue' : gradient < -0.02 ? 'Water leaves tissue' : 'No net movement', caption: 'Particles move across the model membrane down a water-potential gradient.', metrics: [metric('Mass change', mass - 100, ' g'), metric('Water potential', gradient * 10, ' MPa'), metric('Osmosis rate', Math.abs(rate) * 10, ' units/min'), metric('Temperature', temp, '°C')], graph: { label: 'Tissue mass', xLabel: 'Time', yLabel: 'Mass', tone: 'mint', points: series((x) => 100 + (mass - 100) * (1 - Math.exp(-x * 4))) }, bars: [{ label: 'Inside', value: 50 }, { label: 'Outside', value: number(v, 'solutionConc', 0.4) * 100 }, { label: 'Rate', value: Math.abs(rate) * 100 }], readout: `${v.tissue} changes to a predicted mass of ${format(mass)} g after the virtual time course.`, visual: { kind: 'cells', direction: gradient > 0 ? 'Water in' : gradient < 0 ? 'Water out' : 'Balanced', mass: format(mass), cells: particleSet(14).map((cell) => ({ ...cell, opacity: clamp(0.5 + gradient) })) } }); }
function respirometerModel(v) { const temp = number(v, 'temperature', 25); const organismFactor = v.organism === 'Insects' ? 1.35 : 1; const rate = organismFactor * (0.4 + temp / 45); const volume = rate * number(v, 'duration', 10) * 2.5; return result({ status: 'Respiration measured', caption: 'A changing gas volume gives evidence of aerobic respiration.', metrics: [metric('O₂ use', rate, ' mL/min'), metric('Total volume', volume, ' mL'), metric('Q₁₀', 2.1, ''), metric('Temperature', temp, '°C')], graph: { label: 'Gas volume', xLabel: 'Time', yLabel: 'Volume', tone: 'blue', points: series((x) => x * volume) }, bars: [{ label: 'Rate', value: rate * 50 }, { label: 'Time', value: number(v, 'duration', 10) * 5 }, { label: 'Q₁₀', value: 70 }], readout: `${v.organism} consumes an estimated ${format(rate)} mL oxygen per minute in this model.`, visual: { kind: 'bars', bars: [{ label: 'O₂ in', value: 82 }, { label: 'CO₂ out', value: 62 }, { label: 'Heat', value: 34 }], center: `${format(rate)} mL/min`, sub: 'Gas exchange measured' } }); }
function heartModel(v) { const intensity = number(v, 'intensity', 60); const fitness = number(v, 'fitness', 6); const bpm = 65 + intensity * 1.25 - fitness * 2; const breathing = 12 + intensity * 0.25 - fitness * 0.6; const recovery = Math.max(1, 12 - fitness * 0.7 + intensity / 30); return result({ status: 'Exercise response active', caption: 'Heart rate rises to deliver oxygen and recovers after exercise ends.', metrics: [metric('Heart rate', bpm, ' BPM'), metric('Breathing', breathing, ' /min'), metric('Recovery', recovery, ' min'), metric('Intensity', intensity, '%')], graph: { label: 'Heart-rate response', xLabel: 'Time', yLabel: 'BPM', tone: 'coral', points: series((x) => 65 + (bpm - 65) * (1 - Math.exp(-x * 6)) - (x > 0.7 ? (bpm - 65) * (x - 0.7) * 2 : 0)) }, bars: [{ label: 'Rest', value: 40 }, { label: 'Peak', value: bpm / 2 }, { label: 'Recovery', value: 100 - recovery * 5 }], readout: `At ${format(intensity)}% intensity, the subject peaks at ${format(bpm)} BPM and recovers in ${format(recovery)} minutes.`, visual: { kind: 'heart', bpm: format(bpm), phase: 'Exercise phase' } }); }
function soilGrowthModel(v) { const ph = number(v, 'pH', 6.5); const phFactor = Math.max(0, 1 - Math.abs(ph - 6.5) / 4); const nutrients = (number(v, 'nitrogen', 60) + number(v, 'phosphorus', 55)) / 2 / 100; const water = 1 - Math.abs(number(v, 'water', 70) - 70) / 100; const yieldValue = clamp(phFactor * nutrients * water * 120); return result({ status: yieldValue > 65 ? 'Healthy growth' : yieldValue > 35 ? 'Watch for stress' : 'Deficiency symptoms', caption: 'Plant height and leaf colour respond to the balance of soil pH, nutrients and water.', metrics: [metric('Yield potential', yieldValue, '%'), metric('Plant height', yieldValue / 4, ' cm'), metric('Leaf health', yieldValue, '%'), metric('Soil pH', ph, '')], graph: { label: 'Growth over time', xLabel: 'Time', yLabel: 'Height', tone: 'gold', points: series((x) => yieldValue / 4 * (1 - Math.exp(-x * 4))) }, bars: [{ label: 'N', value: number(v, 'nitrogen', 60) }, { label: 'P', value: number(v, 'phosphorus', 55) }, { label: 'Water', value: number(v, 'water', 70) }], readout: `The crop model predicts ${format(yieldValue)}% yield potential. Adjust inputs to correct the visible stress.`, visual: { kind: 'plant', height: yieldValue, health: yieldValue > 65 ? 'Healthy leaves' : 'Stress visible' } }); }
function germinationModel(v) { const temp = Math.max(0, 1 - Math.abs(number(v, 'temperature', 25) - 25) / 25); const moisture = 1 - Math.abs(number(v, 'moisture', 65) - 65) / 100; const oxygen = number(v, 'oxygen', 80) / 100; const light = v.light ? 1 : 0.72; const germinated = clamp(temp * moisture * oxygen * light * 112); return result({ status: germinated > 70 ? 'Favourable conditions' : 'Germination limited', caption: 'Watch the seed tray fill as each environmental condition moves toward or away from its optimum.', metrics: [metric('Germinated', germinated, '%'), metric('Growth rate', germinated / 12, ' mm/day'), metric('Moisture', number(v, 'moisture', 65), '%'), metric('Oxygen', number(v, 'oxygen', 80), '%')], graph: { label: 'Germination percentage', xLabel: 'Days', yLabel: '% germinated', tone: 'mint', points: series((x) => germinated * (1 - Math.exp(-x * 4))) }, bars: [{ label: 'Temp.', value: temp * 100 }, { label: 'Moist.', value: number(v, 'moisture', 65) }, { label: 'O₂', value: number(v, 'oxygen', 80) }], readout: `${format(germinated)}% of the ${v.seed || 'seed'} sample germinates in the current conditions.`, visual: { kind: 'seeds', germinated: format(germinated), rate: format(germinated / 12), seeds: Array.from({ length: 12 }, (_, i) => ({ grown: i < Math.round(germinated / 100 * 12) })) } }); }
function irrigationModel(v) { const soil = optionNumber(v.soil, { Sandy: 0.7, Loam: 1, Clay: 0.85 }); const method = optionNumber(v.method, { Flood: 0.65, Drip: 1, Sprinkler: 0.8 }); const demand = number(v, 'frequency', 5) * number(v, 'amount', 45) / 100; const efficiency = clamp(demand * soil * method * 1.8); const stress = clamp(100 - Math.abs(demand - 2.5) * 18); return result({ status: stress > 65 ? 'Crop adequately watered' : 'Water stress visible', caption: 'Compare irrigation methods by yield achieved per unit of water applied.', metrics: [metric('Efficiency', efficiency, '%'), metric('Plant stress', 100 - stress, '%'), metric('Yield', stress * 0.9, '%'), metric('Water used', demand, ' units')], graph: { label: 'Plant water stress', xLabel: 'Time', yLabel: 'Stress', tone: 'gold', points: series((x) => 100 - stress * (1 - Math.exp(-x * 4))) }, bars: [{ label: 'Applied', value: clamp(demand * 22) }, { label: 'Crop', value: stress }, { label: 'Lost', value: 100 - efficiency }], readout: `${v.method} irrigation delivers ${format(efficiency)}% model water-use efficiency on ${v.soil} soil.`, visual: { kind: 'irrigation', efficiency: format(efficiency), water: stress, method: v.method } }); }
function fertilizerModel(v) { const dose = number(v, 'dose', 60); const typeFactor = optionNumber(v.type, { 'Balanced N-P-K': 1, 'Nitrogen-rich': 0.88, Compost: 0.78 }); const water = number(v, 'water', 70) / 100; const optimum = 75 * typeFactor; const biomass = clamp((dose / optimum) * Math.exp(1 - dose / optimum) * water * 125); return result({ status: dose > optimum * 1.2 ? 'Over-fertilisation risk' : 'Dose-response active', caption: 'Find the point where more fertiliser stops adding useful biomass.', metrics: [metric('Biomass', biomass, '%'), metric('Nutrient uptake', biomass * 0.8, '%'), metric('Optimum dose', optimum, ' kg/ha'), metric('Leaf colour', biomass, '%')], graph: { label: 'Dose-response', xLabel: 'Dose', yLabel: 'Biomass', tone: 'gold', points: series((x) => x * Math.exp(1 - x) * biomass) }, bars: [{ label: 'Dose', value: dose / 150 * 100 }, { label: 'Biomass', value: biomass }, { label: 'Uptake', value: biomass * 0.8 }], readout: `At ${format(dose)} kg/ha, the model biomass is ${format(biomass)}%.`, visual: { kind: 'plant', height: biomass, health: dose > optimum * 1.2 ? 'Leaf burn risk' : 'Crop response' } }); }
function pestModel(v) { const pests = number(v, 'pests', 35); const disease = number(v, 'disease', 20); const controls = optionNumber(v.control, { None: 0, Chemical: 0.75, Biological: 0.62, Cultural: 0.5 }); const damage = clamp((pests * 0.65 + disease * 0.35) * (1 - controls)); const yieldValue = 100 - damage; return result({ status: damage < 25 ? 'Plant health protected' : 'Yield under pressure', caption: 'Compare control strategies while keeping an eye on both yield and wider impacts.', metrics: [metric('Plant health', yieldValue, '%'), metric('Final yield', yieldValue * 0.9, '%'), metric('Damage', damage, '%'), metric('Control impact', controls * 100, '%')], graph: { label: 'Yield over season', xLabel: 'Time', yLabel: 'Yield', tone: 'mint', points: series((x) => 100 - damage * x) }, bars: [{ label: 'Pests', value: pests }, { label: 'Disease', value: disease }, { label: 'Yield', value: yieldValue }], readout: `${v.control} control leaves ${format(yieldValue)}% plant health in the current scenario.`, visual: { kind: 'plant', height: yieldValue, health: `${v.control} control · ${format(damage)}% damage` } }); }
function waterQualityModel(v) { const pollution = number(v, 'fertiliser', 25) * 0.45 + number(v, 'heavyMetals', 10) * 0.35 + number(v, 'oil', 5) * 0.2; const oxygen = clamp(100 - pollution * 0.8 + number(v, 'flow', 50) * 0.2); const turbidity = clamp(pollution * 0.75 - number(v, 'flow', 50) * 0.1); const biodiversity = clamp(100 - pollution * 0.7); return result({ status: oxygen > 60 ? 'Aquatic system stable' : 'Pollution stress visible', caption: 'Water chemistry and organism populations respond together to pollution inputs.', metrics: [metric('Dissolved O₂', oxygen, '%'), metric('pH', 7 - pollution / 55, ''), metric('Turbidity', turbidity, ' NTU'), metric('Biodiversity', biodiversity, '%')], graph: { label: 'Dissolved oxygen', xLabel: 'Time', yLabel: 'O₂', tone: 'blue', points: series((x) => oxygen - turbidity * x * 0.2) }, bars: [{ label: 'O₂', value: oxygen }, { label: 'Turb.', value: turbidity }, { label: 'Bio.', value: biodiversity }], readout: `Pollution pressure is ${format(pollution)} units; the model biodiversity index is ${format(biodiversity)}.`, visual: { kind: 'bars', bars: [{ label: 'O₂', value: oxygen }, { label: 'pH', value: 70 - turbidity / 4 }, { label: 'Bio.', value: biodiversity }], center: `${format(oxygen)}% O₂`, sub: 'Aquatic organisms respond' } }); }
function greenhouseModel(v) { const gases = (number(v, 'co2', 420) - 280) / 10 + (number(v, 'methane', 1.9) - 1.7) * 28; const mitigation = optionNumber(v.mitigation, { None: 0, Reforestation: 12, 'Emission cuts': 22 }); const temperature = Math.max(0.2, gases / 100 - mitigation / 40); const ice = clamp(temperature * 28); return result({ status: temperature > 1.8 ? 'Rapid warming trend' : 'Climate response visible', caption: 'Test how gases, clouds and mitigation change the climate model over time.', metrics: [metric('Warming', temperature, '°C'), metric('Ice melt', ice, '%'), metric('Sea level', ice * 0.8, ' cm'), metric('Mitigation', mitigation, ' impact')], graph: { label: 'Temperature trend', xLabel: 'Years', yLabel: 'Δ°C', tone: 'coral', points: series((x) => temperature * (0.3 + x * 0.7)) }, bars: [{ label: 'CO₂', value: (number(v, 'co2', 420) - 280) / 5 }, { label: 'CH₄', value: number(v, 'methane', 1.9) * 20 }, { label: 'Clouds', value: number(v, 'clouds', 45) }], readout: `${v.mitigation} gives a model warming of +${format(temperature)}°C above the baseline.`, visual: { kind: 'climate', temperature: format(temperature), ice: ice * 2, seaLevel: format(ice * 0.8) } }); }
function carbonModel(v) { const removals = number(v, 'photosynthesis', 60) * 0.8 + number(v, 'ocean', 40) * 0.35; const releases = number(v, 'respiration', 45) * 0.4 + number(v, 'combustion', 25) * 0.7; const co2 = 420 + releases - removals * 0.35; return result({ status: releases > removals ? 'Atmospheric CO₂ rising' : 'Atmospheric CO₂ falling', caption: 'Follow the flux arrows to see which carbon pools gain or lose carbon.', metrics: [metric('Atmospheric CO₂', co2, ' ppm'), metric('Net flux', releases - removals, ' units'), metric('Plant uptake', removals, ' units'), metric('Carbon release', releases, ' units')], graph: { label: 'Atmospheric CO₂', xLabel: 'Time', yLabel: 'ppm', tone: 'mint', points: series((x) => co2 + (releases - removals) * x * 0.4) }, bars: [{ label: 'Photo.', value: number(v, 'photosynthesis', 60) }, { label: 'Resp.', value: number(v, 'respiration', 45) }, { label: 'Fire', value: number(v, 'combustion', 25) }], readout: `The atmosphere contains ${format(co2)} ppm in this scenario because ${releases > removals ? 'releases exceed removals' : 'removals exceed releases'}.`, visual: { kind: 'cycle', co2: format(co2) } }); }
function airQualityModel(v) { const pm = number(v, 'vehicle', 55) * 0.5 + number(v, 'industrial', 40) * 0.7 + number(v, 'domestic', 30) * 0.3; const aqi = clamp(pm * (1 - number(v, 'wind', 45) / 160)); return result({ status: aqi < 50 ? 'Good air quality' : aqi < 100 ? 'Moderate air quality' : 'Health impact high', caption: 'Source controls change the city map; wind disperses but does not remove pollution.', metrics: [metric('Air quality index', aqi, ''), metric('PM2.5', pm * 0.45, ' µg/m³'), metric('NOₓ', pm * 0.3, ' ppb'), metric('SO₂', pm * 0.18, ' ppb')], graph: { label: 'Pollutant concentration', xLabel: 'Time', yLabel: 'AQI', tone: 'coral', points: series((x) => aqi * (0.8 + x * 0.2)) }, bars: [{ label: 'Cars', value: number(v, 'vehicle', 55) }, { label: 'Industry', value: number(v, 'industrial', 40) }, { label: 'Homes', value: number(v, 'domestic', 30) }], readout: `The city AQI is ${format(aqi)}. The largest model source is ${number(v, 'industrial', 40) >= number(v, 'vehicle', 55) ? 'industry' : 'traffic'}.`, visual: { kind: 'city', aqi: format(aqi), smog: aqi, health: aqi < 50 ? 'Low health impact' : 'Reduce exposure', towers: [48, 72, 57, 85, 64, 42] } }); }
function biodiversityModel(v) { const habitat = number(v, 'habitat', 65); const corridors = number(v, 'corridors', 45); const disturbance = number(v, 'disturbance', 30); const protectedBoost = v.protectedArea ? 12 : 0; const species = clamp(habitat * 0.75 + corridors * 0.25 - disturbance * 0.35 + protectedBoost); const risk = clamp(100 - species); return result({ status: risk < 35 ? 'Food web resilient' : 'Fragmentation risk high', caption: 'Connectivity helps species move, feed and reproduce across a changing landscape.', metrics: [metric('Species richness', species, '%'), metric('Extinction risk', risk, '%'), metric('Connectivity', corridors, '%'), metric('Disturbance', disturbance, '%')], graph: { label: 'Species richness', xLabel: 'Time', yLabel: 'Species', tone: 'mint', points: series((x) => species - risk * x * 0.15) }, bars: [{ label: 'Habitat', value: habitat }, { label: 'Corridor', value: corridors }, { label: 'Risk', value: risk }], readout: `${v.protectedArea ? 'Protected habitat is active.' : 'No protected-area boost is active.'} The food web retains ${format(species)}% of baseline richness.`, visual: { kind: 'foodweb', species: format(species), risk: format(risk) } }); }
function resistorNetworkModel(v) { const a = number(v, 'resistorA', 100); const b = number(v, 'resistorB', 220); const eq = v.connection === 'Parallel' ? (a * b) / (a + b) : a + b; const current = number(v, 'voltage', 9) / eq * 1000; return result({ status: 'Network powered', caption: 'Compare equivalent resistance and branch current in the two arrangements.', metrics: [metric('Equivalent R', eq, ' Ω'), metric('Total current', current, ' mA'), metric('Power', number(v, 'voltage', 9) * current, ' mW'), metric('Branch B', number(v, 'voltage', 9) / b * 1000, ' mA')], graph: { label: 'Current vs voltage', xLabel: 'Voltage', yLabel: 'Current', tone: 'blue', points: series((x) => x * current) }, bars: [{ label: 'R₁', value: a / 10 }, { label: 'R₂', value: b / 10 }, { label: 'I', value: current * 5 }], readout: `${v.connection} network has an equivalent resistance of ${format(eq)} Ω.`, visual: { kind: 'circuit', active: true, current: format(current, 1) } }); }
function logicModel(v) { const a = Boolean(v.inputA); const b = Boolean(v.inputB); let output = v.gate === 'AND' ? a && b : v.gate === 'OR' ? a || b : v.gate === 'NOT' ? !a : v.gate === 'NAND' ? !(a && b) : a !== b; return result({ status: output ? 'Output HIGH · LED on' : 'Output LOW · LED off', caption: 'Toggle the inputs and build a truth table row by row.', metrics: [metric('Input A', a ? 1 : 0, ''), metric('Input B', b ? 1 : 0, ''), metric('Output', output ? 1 : 0, ''), metric('Gate', 1, v.gate)], graph: { label: 'Truth-table output', xLabel: 'Input rows', yLabel: 'Logic level', tone: 'blue', points: series((x) => output ? 1 : 0) }, bars: [{ label: 'A', value: a ? 100 : 12 }, { label: 'B', value: b ? 100 : 12 }, { label: 'OUT', value: output ? 100 : 12 }], readout: `${v.gate} returns ${output ? 1 : 0} for A=${a ? 1 : 0}, B=${b ? 1 : 0}.`, visual: { kind: 'logic', gate: v.gate, a, b, output } }); }
function transistorModel(v) { const base = number(v, 'baseCurrent', 8); const amplitude = number(v, 'amplitude', 2); const amplifier = v.mode === 'Amplifier'; const current = Math.min(40, base * (amplifier ? 2.2 : 1.6)); const gain = amplifier ? Math.min(18, base / 2 + amplitude * 2) : 0; const region = base < 3 ? 'Cutoff' : base > 14 ? 'Saturation' : 'Active region'; return result({ status: region, caption: amplifier ? 'A small input signal is amplified until the transistor leaves its linear region.' : 'Use base current to move the transistor between off and on.', metrics: [metric('Collector current', current, ' mA'), metric('Voltage gain', gain, '×'), metric('LED brightness', current / 40 * 100, '%'), metric('Input amplitude', amplitude, ' V')], graph: { label: 'Input-output characteristic', xLabel: 'Base current', yLabel: 'Collector current', tone: 'gold', points: series((x) => Math.min(1, x * (base / 10 + 0.2))) }, bars: [{ label: 'Base', value: base * 5 }, { label: 'Collector', value: current / 40 * 100 }, { label: 'Gain', value: gain * 5 }], readout: `The transistor is in the ${region.toLowerCase()} at ${format(base)} µA base current.`, visual: { kind: 'transistor', current: format(current), region, on: current > 5, path: series((x) => 100 - x * 70, 20).map((p) => `${20 + p.x * 170},${p.y}`).join(' ') } }); }
function rcModel(v) { const tau = number(v, 'resistance', 20) * number(v, 'capacitance', 30); const level = v.mode === 'Discharging' ? 100 * Math.exp(-1.5 / Math.max(tau / 100, 0.1)) : 100 * (1 - Math.exp(-1.5 / Math.max(tau / 100, 0.1))); const voltage = number(v, 'voltage', 5) * level / 100; return result({ status: v.mode === 'Charging' ? 'Capacitor charging' : 'Capacitor discharging', caption: 'The time constant controls how quickly voltage and current change.', metrics: [metric('Time constant', tau, ' ms'), metric('Capacitor voltage', voltage, ' V'), metric('Current', (100 - level) / 10, ' mA'), metric('Charge level', level, '%')], graph: { label: 'Capacitor voltage', xLabel: 'Time', yLabel: 'Voltage', tone: 'blue', points: series((x) => v.mode === 'Discharging' ? Math.exp(-x * 4) : 1 - Math.exp(-x * 4)) }, bars: [{ label: 'R', value: number(v, 'resistance', 20) }, { label: 'C', value: number(v, 'capacitance', 30) }, { label: 'τ', value: tau / 100 }], readout: `${v.mode} reaches ${format(level)}% of the supply after the model time window.`, visual: { kind: 'rc', tau: format(tau), level, full: level > 90 } }); }
function feedbackModel(v) { const input = number(v, 'sensorValue', 65); const threshold = number(v, 'threshold', 50); const active = input >= threshold; return result({ status: active ? 'Actuator active' : 'Actuator idle', caption: 'Move the sensed input across the threshold to test the control response.', metrics: [metric('Sensor value', input, '%'), metric('Threshold', threshold, '%'), metric('Error', input - threshold, '%'), metric('Output', active ? 1 : 0, '')], graph: { label: 'Sensor-response curve', xLabel: 'Input', yLabel: 'Output', tone: 'mint', points: series((x) => x * 100 >= threshold ? 1 : 0) }, bars: [{ label: 'Input', value: input }, { label: 'Limit', value: threshold }, { label: 'Output', value: active ? 100 : 10 }], readout: `${v.sensor} sensor at ${format(input)}% is ${active ? 'above' : 'below'} the ${format(threshold)}% threshold.`, visual: { kind: 'feedback', input, threshold, active, actuator: v.actuator, angle: -45 + input * 0.9 } }); }
function particleSet(count) { return Array.from({ length: Math.max(4, Math.min(28, count)) }, (_, index) => ({ x: (index * 37 + 11) % 88 + 4, y: (index * 53 + 17) % 70 + 10, delay: (index % 5) * 0.2 })); }
function genericModel(v) { return result({ status: 'Live model', caption: 'The virtual result updates as inputs change.', metrics: [metric('Response', 68, '%'), metric('Samples', 12, ''), metric('Change', 24, '%'), metric('Confidence', 92, '%')], graph: { label: 'Live response', xLabel: 'Input', yLabel: 'Output', points: series((x) => x ** 0.7), tone: 'green' }, bars: [{ label: 'A', value: 70 }, { label: 'B', value: 54 }, { label: 'C', value: 82 }], readout: 'Use the controls to generate a new observation.', visual: { kind: 'generic', center: 'Live response', sub: 'Model output updates with your inputs' } });
}
